    'pluginCreatePrompt': 'Help me create a ConeCode plugin. Ask three things first, then act: what it is called, the concrete problem it solves, and whether it needs AI execution (only then write a skill).\n\nRules:\n1. Plugins are plugins, skills are skills: a plugin is metadata (name, description) plus an optional view; a skill is instructions for the AI (SKILL.md). Never mix them.\n2. If AI execution is needed: write name, description (must include one English line starting with "Use when"), and body (trigger conditions first, then read-only steps, then report format; check only, do not fix unless I explicitly say so), and paste the full text for me to copy.\n3. Then give me the two manual steps: create and paste it under Settings → Skills, then link it with the add form under Settings → Plugins.\n4. For plugins without AI execution (display-only, jump-only): just give me a name and a one-line description, I will add it in the library form myself.',
